import customers from './customers.json' with {type:'json'};

export async function listTools() {
  return [
    {
      name: 'customer_lookup',
      description: 'Look up a customer by their unique customer ID.',
      inputSchema: {
        type: 'object',
        properties: {
          customer_id: {
            type: 'string',
            description: 'The unique identifier of the customer to look up.',
          },
        },
        required: ['customer_id'],
        additionalProperties: false,
      },
    },
  ];
}

export async function callTool(name, args) {
  if (name !== 'customer_lookup') {
    throw new Error(`Unknown tool: ${name}`);
  }

  const id = args && args.customer_id;
  if (typeof id !== 'string') {
    throw new Error('Invalid arguments: customer_id must be a string');
  }

  const customer = customers[id];
  if (!customer) {
    throw new Error(`Customer not found: ${id}`);
  }

  return {
    content: [
      { type: 'text', text: `Name: ${customer.name}, Tier: ${customer.tier}` },
    ],
  };
}

